const q = (v) => parseFloat(String(v ?? 0)) || 0;
const bumpIn = (map, wh, item, itemName, qty) => {
  if (!wh || !item || qty <= 0) return;
  const key = `${wh}::${item}`;
  if (!map.has(key)) map.set(key, { warehouse: wh, item, item_name: itemName, qty_in: 0, qty_out: 0, balance: 0 });
  const a = map.get(key);
  a.qty_in += qty;
  a.balance += qty;
};
const bumpOut = (map, wh, item, itemName, qty) => {
  if (!wh || !item || qty <= 0) return;
  const key = `${wh}::${item}`;
  if (!map.has(key)) map.set(key, { warehouse: wh, item, item_name: itemName, qty_in: 0, qty_out: 0, balance: 0 });
  const a = map.get(key);
  a.qty_out += qty;
  a.balance -= qty;
};
const all = await $zodula.doctype("Stock Entry Item").select().limit(10000);
const parentCache = new Map();
const bucket = new Map();
for (const row of all.docs ?? []) {
  const parentId = String((row || {}).parentid || "").trim();
  if (!parentId) continue;
  if (!parentCache.has(parentId)) {
    const parent = await $zodula.doctype("Stock Entry").get(parentId).catch(() => null);
    parentCache.set(parentId, parent);
  }
  const parent = parentCache.get(parentId);
  if (!parent || String((parent || {}).doc_status || "") !== "Submitted") continue;
  const item = String((row || {}).item || "").trim();
  if (!item) continue;
  const src = String((row || {}).source_warehouse || "").trim();
  const tgt = String((row || {}).target_warehouse || "").trim();
  if (!src && !tgt) continue;
  const qty = Math.abs(q((row || {}).quantity));
  if (qty <= 0) continue;
  const name = String((row || {}).item_name || "");
  if (tgt) bumpIn(bucket, tgt, item, name, qty);
  if (src) bumpOut(bucket, src, item, name, qty);
}
const rows = Array.from(bucket.values()).sort((a, b) => {
  const wa = String(a.warehouse || "");
  const wb = String(b.warehouse || "");
  if (wa < wb) return -1;
  if (wa > wb) return 1;
  const ia = String(a.item || "");
  const ib = String(b.item || "");
  if (ia < ib) return -1;
  if (ia > ib) return 1;
  return 0;
});
const columns = [
  { key: "warehouse", label: "Warehouse", sortable: true },
  { key: "item", label: "Item", sortable: true },
  { key: "item_name", label: "Item Name", sortable: true },
  { key: "qty_in", label: "Qty In", sortable: true },
  { key: "qty_out", label: "Qty Out", sortable: true },
  { key: "balance", label: "Balance", sortable: true }
];
return { rows, columns, count: rows.length };
